#!/bin/bash
# Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# A provider sandbox needs `/sandbox/.claude.json` seeded with onboarding done
# and the API key approved. Without it Claude Code's TUI runs its "Anthropic
# services" reachability check before it reads ANTHROPIC_BASE_URL and dies on
# the blocked api.anthropic.com, while `claude -p` works.
#
# Covers seed_claude_json() in scripts/sandbox.sh: the seed's contents, that it
# carries only the key's last 20 characters (what the CLI records), that it is
# merged into an existing file rather than written over it, and that no provider
# task means no openshell call at all.
#
# Run: tests/test-claude-seed.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "${SCRIPT_DIR}/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

HELPERS="${TMP}/helpers.sh"
sed -n '/^seed_claude_json()/,/^}/p' "${REPO_ROOT}/scripts/sandbox.sh" > "$HELPERS"
# shellcheck disable=SC1090
source "$HELPERS"

run() { "$@"; }
# From lib.sh; the seed only applies to profiles that may carry a provider.
personal_profile() { [[ "$1" == personal || "$1" == home ]]; }
# shellcheck disable=SC2034 # read by the sourced seed_claude_json()
SANDBOX_PROFILE=work
# shellcheck disable=SC2034 # read by the sourced seed_claude_json()
GW_FLAG=()

CALL_LOG="${TMP}/calls.log"
CAPTURE_DIR="${TMP}/captured"
mkdir -p "${TMP}/bin" "$CAPTURE_DIR"
export CALL_LOG CAPTURE_DIR

# Records every call; for `sandbox upload` it keeps the source file, so the
# seed's content can be asserted without a real sandbox.
cat > "${TMP}/bin/openshell" <<'FAKE'
#!/bin/bash
printf '%s\n' "$*" >> "$CALL_LOG"
args=("$@")
if [[ "${args[0]} ${args[1]}" == "sandbox upload" ]]; then
    src="${args[${#args[@]}-2]}"
    cp "$src" "${CAPTURE_DIR}/$(basename "$src")"
fi
exit 0
FAKE
chmod +x "${TMP}/bin/openshell"
export PATH="${TMP}/bin:${PATH}"

fail=0
KEY="sk-test-0123456789abcdefghij-LASTTWENTYCHARS"
KEY_TAIL="${KEY: -20}"

# No provider: Anthropic direct or Vertex needs no seed, and writing one would
# claim an approval the host never made.
: > "$CALL_LOG"
# The host running the tests is itself a provider session; drop its vars.
unset ANTHROPIC_BASE_URL ANTHROPIC_API_KEY
seed_claude_json sb-none
if [[ -s "$CALL_LOG" ]]; then
    echo "FAIL: seeded without a provider URL" >&2
    cat "$CALL_LOG" >&2
    fail=1
fi

# Provider: seed written, key tail only.
: > "$CALL_LOG"
ANTHROPIC_BASE_URL="https://provider.example.invalid" ANTHROPIC_API_KEY="$KEY" \
    seed_claude_json sb-provider

grep -q '/sandbox' "$CALL_LOG" \
    || { echo "FAIL: seed not uploaded to /sandbox" >&2; fail=1; }
SEED="${CAPTURE_DIR}/.claude-seed.json"
[[ -f "$SEED" ]] || { echo "FAIL: no .claude-seed.json staged" >&2; exit 1; }

jq -e '.hasCompletedOnboarding == true' "$SEED" >/dev/null \
    || { echo "FAIL: seed does not mark onboarding complete" >&2; fail=1; }
jq -e --arg t "$KEY_TAIL" '.customApiKeyResponses.approved == [$t]' "$SEED" >/dev/null \
    || { echo "FAIL: seed does not approve the key's last 20 characters" >&2; fail=1; }
if grep -qF "$KEY" "$SEED"; then
    echo "FAIL: seed carries the whole API key" >&2
    fail=1
fi

# An existing .claude.json holds session state; the seed must be merged into it.
grep -qF 'jq -s' "$CALL_LOG" \
    || { echo "FAIL: seed would overwrite an existing .claude.json" >&2; fail=1; }
grep -qF 'mv /sandbox/.claude-seed.json' "$CALL_LOG" \
    || { echo "FAIL: no fallback write for a sandbox with no .claude.json" >&2; fail=1; }

[[ $fail -eq 0 ]] && echo 'all claude-seed checks passed'
exit $fail
